#!/usr/bin/env python3
import rclpy
from rclpy.node import Node
from sensor_msgs.msg import Imu

class ImuListener(Node):
    def __init__(self):
        super().__init__('imu_listener')
        # Subscribe to fused IMU data
        self.subscription = self.create_subscription(
            Imu,
            '/mavros/imu/data',
            self.imu_callback,
            10)
        self.subscription  # prevent unused variable warning

    def imu_callback(self, msg: Imu):
        # Orientation (quaternion)
        q = msg.orientation
        self.get_logger().info(
            f"Orientation -> x:{q.x:.3f}, y:{q.y:.3f}, z:{q.z:.3f}, w:{q.w:.3f}"
        )

        # Angular velocity (rad/s)
        av = msg.angular_velocity
        self.get_logger().info(
            f"Angular Vel -> x:{av.x:.3f}, y:{av.y:.3f}, z:{av.z:.3f}"
        )

        # Linear acceleration (m/s^2)
        la = msg.linear_acceleration
        self.get_logger().info(
            f"Linear Acc -> x:{la.x:.3f}, y:{la.y:.3f}, z:{la.z:.3f}"
        )

def main(args=None):
    rclpy.init(args=args)
    node = ImuListener()
    rclpy.spin(node)
    node.destroy_node()
    rclpy.shutdown()

if __name__ == '__main__':
    main()

